const event = $input.first().json.body || $input.first().json;
const data = event.data || {};
const message =
  data.message ||
  data.whatsappInboundMessage ||
  event.message ||
  event.whatsappInboundMessage ||
  {};

const profile = data.customerProfile || data.profile || {};

const type = String(message.type || 'text');

let content =
  message.text?.body ||
  message.body ||
  '';

if (type === 'interactive') {
  content =
    message.interactive?.button_reply?.id ||
    message.interactive?.list_reply?.id ||
    '';
}

if (type === 'button') {
  content = message.button?.text || '';
}

if (type === 'image') {
  content = message.image?.caption || '[image]';
}

if (type === 'audio' || type === 'voice') {
  content = '[voice note]';
}

return [{
  json: {
    event_type: event.type || '',
    message_id: String(
      message.id ||
      data.messageId ||
      event.messageId ||
      event.id ||
      ''
    ),

    phone: String(
      message.from ||
      message.sender?.phone ||
      data.from ||
      event.from ||
      ''
    ),

    // IMPORTANT:
    // Use YCloud's real BSUID when available.
    // Never fall back to phone number.
    channel_user_id: message.fromUserId
      ? String(message.fromUserId)
      : null,

    customer_name: String(
      profile.name ||
      message.customerProfile?.name ||
      ''
    ),

    message_type: type,
    content: String(content),
    direction: 'inbound',
    sender: 'customer',
    ai_intent: ''
  }
}];

const input = $('Extract Inbound Message').first().json;
const context = $('Retrieve Chat Context').first().json || {};
return [{ json: { customer_phone: input.phone, customer_name: input.customer_name, message: input.content, context } }];

const input = $('Extract Inbound Message').first().json;
const context = $('Retrieve Chat Context').first().json || {};

const text = String(input.content || '').trim();

const match = text.match(/^btn_(confirm|cancel):([A-Z0-9-]+)$/i);

let route = 'ai';
let response = null;

// 1. Staff takeover
if (context.session && context.session.ai_enabled === false) {
  route = 'staff';
}

// 2. Restaurant closed
else if (context.is_open === false) {
  route = 'response';

  const message =
    'Pabbas is currently closed. Please try again during our opening hours.';

  response = {
    customer_phone: input.phone,
    log_text: message,
    outgoing: {
      type: 'text',
      text: {
        body: message
      }
    }
  };
}

// 3. Order confirmation/cancellation buttons
else if (match) {
  route = match[1].toLowerCase();
}

// 4. Greeting
else if (/^(hi|hello|hey|menu|start)$/i.test(text)) {
  route = 'response';

  const firstName = input.customer_name
    ? String(input.customer_name).trim().split(/\s+/)[0]
    : '';

  const message = firstName
    ? `Hello ${firstName}! ?? Welcome to Pabbas. How can I help you today?`
    : `Hello! ?? Welcome to Pabbas. How can I help you today?`;

  response = {
    customer_phone: input.phone,
    log_text: message,
    outgoing: {
      type: 'text',
      text: {
        body: message
      }
    }
  };
}

// 5. Everything else goes to AI
else {
  route = 'ai';
}

return [{
  json: {
    route,
    order_number: match ? match[2].toUpperCase() : null,
    customer_phone: input.phone,
    customer_name: input.customer_name,
    channel_user_id: input.channel_user_id || null,
    response
  }
}];

