const button = source.message.match(/^btn_(confirm|cancel):([A-Z0-9-]+)$/i);
if (button) { out.action = button[1].toLowerCase(); out.order_number = button[2].toUpperCase(); out.reply = ''; return [{ json: out }]; }
let parsed = null;
try { const a = raw.indexOf('{'); const b = raw.lastIndexOf('}'); if (a >= 0 && b > a) parsed = JSON.parse(raw.slice(a, b + 1)); } catch {}
if (!parsed || parsed.intent !== 'order') { out.reply = String(parsed?.reply || out.reply); return [{ json: out }]; }
