for (const candidate of (Array.isArray(parsed.items) ? parsed.items : [])) { const item = menu.get(norm(candidate?.name)); const quantity = Math.round(Number(candidate?.quantity)); if (!item || !Number.isInteger(quantity) || quantity < 1 || quantity > 50) { out.reply = !item ? 'That item is not on the current Pabbas menu.' : 'Please choose a quantity between 1 and 50.'; return [{ json: out }]; } out.items.push({ name: item.name, quantity, price: item.price }); }
if (!out.items.length) { out.reply = String(parsed.reply || out.reply); return [{ json: out }]; }
const open = context.open_order || null;
out.action = open ? 'amend' : 'create';
out.order_number = open?.order_number || null;
out.order_type = ['delivery', 'takeaway', 'dine-in'].includes(String(parsed.order_type || '').toLowerCase()) ? String(parsed.order_type).toLowerCase() : (open?.order_type || 'delivery');
out.total = out.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
