  route.customer_phone ||
  ''
).trim();

const customerName = String(
  input.customer_name ||
  input.name ||
  inbound.customer_name ||
  route.customer_name ||
  ''
).trim();

const channelUserId = String(
  input.channel_user_id ||
  inbound.channel_user_id ||
  ''
).trim();


