// NORMAL REPLY / GREETING / AI
// ==================================================

else if (action === 'reply') {

  const ctx = $('Retrieve Chat Context').first()?.json || {};
  const isNew = !ctx.history || ctx.history.length === 0;

  // Checking if they explicitly clicked our buttons
  const isMenuIntent = (String(inbound.content).toLowerCase().includes('btn_menu') || String(inbound.content).toLowerCase().includes('btn_order') || String(inbound.content).toLowerCase().includes('explore menu') || String(inbound.content).toLowerCase().includes('order now'));

  text = `${reply}`;

  if (ctaUrl && (isNew || isMenuIntent)) {
    interactive = {
      type: 'button',
      body: {
        text: `${reply}\n\nReady to browse the menu or place an order?`
      },
      action: {
        buttons: [
          {
            type: 'reply',
            reply: {
              id: `btn_order`,
              title: '🛍️ Order Now'
            }
          },
          {
            type: 'reply',
            reply: {
              id: `btn_menu`,
              title: '🍦 Explore Menu'
            }
          },
          {
            type: 'reply',
            reply: {
              id: `btn_ask`,
              title: '💬 Ask Me Anything'
            }
          }
        ]
      }
    };
  } else if (ctaUrl) {
    // If not new and not explicitly requested, just append plain text URL gracefully if we want, or do nothing.
    // We will do nothing to avoid spamming the CTA.
  }
}


// --------------------------------------------------
// FINAL OUTGOING PAYLOAD
// --------------------------------------------------

const outgoing = interactive
  ? {
      type: 'interactive',
      interactive
    }
  : {
      type: 'text',
      text: {
        body: text
      }
    };


// --------------------------------------------------
// RETURN
// --------------------------------------------------

return [
  {
    json: {

      customer_phone: phone,

      customer_name: customerName,

      channel_user_id: channelUserId,

      order_number: orderNumber || null,

      action,

      log_text: text,

      outgoing,

      ycloud_payload: {
        from: '+919180348124',
        to: phone,
        ...outgoing
      }
    }
  }
];

const input = $input.first().json || {};

/*
 * Preserve everything received from
 * Resolve Customer Identity for CTA.
 *
 * Do NOT return only { cta_ready } because
 * Build Outbound Message also needs the customer
 * phone and the original response data.
 */

const phone = String(
  input.phone ||
  input.customer_phone ||
  ''
).trim();

const channelUserId = String(
  input.channel_user_id ||
  ''
).trim();

const name = String(
  input.name ||
  input.customer_name ||
  ''
).trim();

const ctaUrl = String(
  input.cta_url ||
  ''
).trim();

const ctaReady =
  Boolean(phone) &&
  Boolean(channelUserId) &&
  Boolean(ctaUrl);

return [
  {
    json: {
      ...input,

      customer_phone: phone,
      customer_name: name,
      channel_user_id: channelUserId,

      cta_url: ctaUrl,
      cta_ready: ctaReady
    }
  }
];
